## Why This Is Asked
Tests ability to reason about worst-case guarantees and practical trade-offs between quicksort and mergesort, including depth control, partition balance, and memory usage in a real-world data processing pipeline.

## Key Concepts
- Hybrid sorting (introspective sort)
- Worst-case guarantees, space complexity
- Handling duplicates, stability considerations
- Practical performance on sorted/partially sorted data

## Code Example
```cpp
#include <vector>
#include <algorithm>
#include <cmath>

// Simplified hybrid sort: quicksort with depth limit, switch to mergesort when needed
int partition(std::vector<long long>& a, int l, int r) {
  long long pivot = a[(l + r) / 2];
  int i = l, j = r;
  while (i <= j) {
    while (a[i] < pivot) ++i;
    while (a[j] > pivot) --j;
    if (i <= j) std::swap(a[i++], a[j--]);
  }
  return i;
}

void mergeSort(std::vector<long long>& a, int l, int r, std::vector<long long>& tmp) {
  if (r - l <= 1) return;
  int m = (l + r) / 2;
  mergeSort(a, l, m, tmp);
  mergeSort(a, m, r, tmp);
  int i = l, j = m, k = 0;
  while (i < m || j < r) {
    if (j >= r || (i < m && a[i] <= a[j])) tmp[k++] = a[i++];
    else tmp[k++] = a[j++];
  }
  for (int t = 0; t < k; ++t) a[l + t] = tmp[t];
}

void hybridSort(std::vector<long long>& a, int l, int r, int depth, int depthLimit) {
  if (r - l <= 16) {
    std::sort(a.begin() + l, a.begin() + r + 1);
    return;
  }
  if (depth >= depthLimit) {
    std::vector<long long> tmp(r - l + 1);
    mergeSort(a, l, r + 1, tmp);
    return;
  }
  int p = partition(a, l, r);
  hybridSort(a, l, p - 1, depth + 1, depthLimit);
  hybridSort(a, p, r, depth + 1, depthLimit);
}

// Entry: call with depth=0 and depthLimit=2*log2(n)
```

## Why This Is Asked
Tests knowledge of Trie data structures, deduplication strategies, and efficient prefix queries—essential skills for building autocomplete systems.

## Key Concepts
- Trie with per-node subtree counts for O(1) prefix counting
- Deduplication via global set to maintain word uniqueness
- Prefix-based retrieval with controlled result limits
- Lexicographic ordering through systematic child traversal

## Code Example
```javascript
class TrieNode {
  constructor() {
    this.next = new Map();
    this.isWord = false;
    this.passCount = 0;
  }
}

class Trie {
  constructor() {
    this.root = new TrieNode();
    this.wordSet = new Set();
  }

  insert(word) {
    if (this.wordSet.has(word)) return;
    this.wordSet.add(word);
    let node = this.root;
    for (const char of word) {
      if (!node.next.has(char)) {
        node.next.set(char, new TrieNode());
      }
      node = node.next.get(char);
      node.passCount++;
    }
    node.isWord = true;
  }

  countPrefix(prefix) {
    let node = this.root;
    for (const char of prefix) {
      if (!node.next.has(char)) return 0;
      node = node.next.get(char);
    }
    return node.passCount;
  }

  listWithPrefix(prefix, limit) {
    let node = this.root;
    for (const char of prefix) {
      if (!node.next.has(char)) return [];
      node = node.next.get(char);
    }
    const result = [];
    this.dfs(node, prefix, result, limit);
    return result;
  }

  dfs(node, current, result, limit) {
    if (result.length >= limit) return;
    if (node.isWord) {
      result.push(current);
    }
    const sortedKeys = Array.from(node.next.keys()).sort();
    for (const char of sortedKeys) {
      this.dfs(node.next.get(char), current + char, result, limit);
    }
  }
}
```

